-- App Review access. Apple's reviewer needs to see a family with real-looking
-- drives, so this adds one sample family that only holds made-up data, and a
-- code (APPREVIEW) that anyone can use again and again to join it as a parent.
-- Times are set relative to when this runs, so the drives look recent.

ALTER TABLE families ADD COLUMN demo INTEGER NOT NULL DEFAULT 0;
ALTER TABLE invites ADD COLUMN reusable INTEGER NOT NULL DEFAULT 0;

VALUES ('demo-family', 'Sample Family', 25, 80, (CAST(strftime('%s','now') AS INTEGER) * 1000) - 14 * 86400000, 1);

  last_lat, last_lng, last_speed_mps, last_heading, created_at)
